import{c as a,Q as i,j as e,m as l}from"./chunks/framework.DOi4mjdC.js";const c=JSON.parse('{"title":"TilingData结构体","description":"","frontmatter":{},"headers":[{"level":1,"title":"TilingData结构体","slug":"tilingdata结构体"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"参数说明","slug":"参数说明"}],"relativePath":"api/SIMD-API/高阶API/HCCL通信类/HCCL-Tiling侧接口/TilingData结构体.md","filePath":"api/SIMD-API/高阶API/HCCL通信类/HCCL-Tiling侧接口/TilingData结构体.md"}'),n={name:"api/SIMD-API/高阶API/HCCL通信类/HCCL-Tiling侧接口/TilingData结构体.md"};function r(d,t,o,g,h,s){return i(),e("div",null,[...t[0]||(t[0]=[l('<h1 id="tilingdata结构体" tabindex="-1">TilingData结构体 <a class="header-anchor" href="#tilingdata结构体" aria-label="Permalink to &quot;TilingData结构体&quot;">​</a></h1><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>在算子实现中，由Tiling组装通信配置项，核函数实现时将Tiling配置项通过入参传递给Kernel侧通信API做通信计算。本节TilingData结构体包括<a href="#table4835205712588">Mc2InitTiling</a>和<a href="#table678914014562">Mc2CcTiling</a>，这两个结构体均通过调用<a href="./GetTiling-100.html">GetTiling</a>接口返回。其中，<a href="#table678914014562">Mc2CcTiling</a>为具体每个通信任务的参数配置，当算子中有多个通信任务时，可定义多个<a href="#table678914014562">Mc2CcTiling</a>参数（最多支持定义8个）。</p><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p><strong>表 1</strong> Mc2InitTiling参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>reserved</td><td>初始化通信任务配置。uint8_t *类型，支持最大长度64字节，该结构体仅支持通过接口GetTiling获取。</td></tr></tbody></table><p><strong>表 2</strong> Mc2CcTiling参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>reserved</td><td>各通信域中每个通信任务的参数配置。uint8_t *类型，支持最大长度280字节，该结构体仅支持通过接口GetTiling获取。注意，最多支持配置8个通信任务。</td></tr></tbody></table>',8)])])}const _=a(n,[["render",r]]);export{c as __pageData,_ as default};
